import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import java.io.*;
import java.util.logging.*;

@WebServlet("/api/users")
public class UserSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(UserSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String searchTerm = req.getParameter("q");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");

        if (searchTerm == null || searchTerm.isEmpty()) {
            resp.sendError(400, "Missing search parameter");
            return;
        }

        // Input length validation
        if (searchTerm.length() > 100) {
            resp.sendError(400, "Search term too long");
            return;
        }

        // Basic alphanumeric check for sort column (allowlist)
        if (sortCol != null && !sortCol.matches("^[a-zA-Z_]+$")) {
            sortCol = "last_name";
        }
        if (sortCol == null) sortCol = "last_name";

        // Build query - department filter uses parameterized approach
        // but search uses LIKE with concatenation for wildcard support
        String query = "SELECT employee_id, first_name, last_name, email, department " +
                       "FROM employees WHERE (first_name LIKE '%" + searchTerm + "%' " +
                       "OR last_name LIKE '%" + searchTerm + "%' " +
                       "OR email LIKE '%" + searchTerm + "%')";

        if (department != null && !department.isEmpty()) {
            query += " AND department = ?";
        }
        query += " ORDER BY " + sortCol + " LIMIT 50";

        log.info("User search: q=" + searchTerm.substring(0, Math.min(10, searchTerm.length())) + "...");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(query)) {

            if (department != null && !department.isEmpty()) {
                stmt.setString(1, department);
            }

            ResultSet rs = stmt.executeQuery();
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                first = false;
                out.printf("  {\"id\": %d, \"first_name\": \"%s\", \"last_name\": \"%s\", \"email\": \"%s\", \"dept\": \"%s\"}",
                    rs.getInt("employee_id"),
                    escapeJson(rs.getString("first_name")),
                    escapeJson(rs.getString("last_name")),
                    escapeJson(rs.getString("email")),
                    escapeJson(rs.getString("department")));
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private String escapeJson(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
